CREATE TABLE tenant (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, code VARCHAR(40) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE store (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), name VARCHAR(120) NOT NULL, code VARCHAR(40) NOT NULL, timezone VARCHAR(50) NOT NULL DEFAULT 'Asia/Shanghai', active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0, UNIQUE(tenant_id, code));
CREATE TABLE app_user (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), login_name VARCHAR(80) NOT NULL, display_name VARCHAR(120) NOT NULL, password_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0, UNIQUE(tenant_id, login_name));
CREATE TABLE role (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), code VARCHAR(50) NOT NULL, name VARCHAR(80) NOT NULL, UNIQUE(tenant_id, code));
CREATE TABLE user_role (user_id UUID NOT NULL REFERENCES app_user(id), role_id UUID NOT NULL REFERENCES role(id), PRIMARY KEY(user_id, role_id));
CREATE TABLE user_store_scope (user_id UUID NOT NULL REFERENCES app_user(id), store_id UUID NOT NULL REFERENCES store(id), PRIMARY KEY(user_id, store_id));
CREATE TABLE technician (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), code VARCHAR(40) NOT NULL, name VARCHAR(80) NOT NULL, phone VARCHAR(30), queue_order INTEGER NOT NULL DEFAULT 0, employment_status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK (employment_status IN ('ACTIVE','INACTIVE','LEFT')), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0, UNIQUE(store_id, code));
CREATE INDEX technician_store_queue_idx ON technician(tenant_id, store_id, active, queue_order);
CREATE TABLE room (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), code VARCHAR(40) NOT NULL, name VARCHAR(80) NOT NULL, room_type VARCHAR(40) NOT NULL DEFAULT 'STANDARD', bed_count SMALLINT NOT NULL DEFAULT 1 CHECK (bed_count > 0), active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0, UNIQUE(store_id, code));
CREATE TABLE service_item (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), code VARCHAR(40) NOT NULL, name VARCHAR(120) NOT NULL, category VARCHAR(60) NOT NULL DEFAULT 'MASSAGE', default_duration_minutes SMALLINT NOT NULL CHECK(default_duration_minutes BETWEEN 15 AND 360), price_cents INTEGER NOT NULL CHECK(price_cents >= 0), requires_room BOOLEAN NOT NULL DEFAULT TRUE, allows_extension BOOLEAN NOT NULL DEFAULT TRUE, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), version BIGINT NOT NULL DEFAULT 0, UNIQUE(store_id, code));
CREATE TABLE audit_log (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID, actor_user_id UUID, action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id UUID NOT NULL, before_data JSONB, after_data JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
